614	    <script>
615	        document.addEventListener('DOMContentLoaded', function() {
616	            document.getElementById('year').textContent = new Date().getFullYear();
617	
618	            const menuToggle = document.querySelector('.menu-toggle');
619	            const navMenu = document.getElementById('nav-menu');
620	
621	            if (menuToggle) {
622	                menuToggle.addEventListener('click', function() {
623	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
624	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
625	                    navMenu.toggleAttribute('hidden');
626	                });
627	
628	                const navLinks = navMenu.querySelectorAll('a');
629	                navLinks.forEach(link => {
630	                    link.addEventListener('click', function() {
631	                        menuToggle.setAttribute('aria-expanded', 'false');
632	                        navMenu.setAttribute('hidden', '');
633	                    });
634	                });
635	            }
636	
637	            const learnMoreBtn = document.getElementById('learn-more-btn');
638	            if (learnMoreBtn) {
639	                learnMoreBtn.addEventListener('click', function() {
640	                    const getStartedSection = document.getElementById('get-started');
641	                    if (getStartedSection) {
642	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
643	                        document.getElementById('name').focus();
644	                    }
645	                });
646	            }
647	
648	            const contactForm = document.getElementById('contact-form');
649	            if (contactForm) {
650	                const showError = (field, message) => {
651	                    const error = field.parentElement.querySelector('.field-error');
652	                    if (error) {
653	                        error.classList.add('show');
654	                        error.textContent = message;
655	                    }
656	                    field.setAttribute('aria-invalid', 'true');
657	                };
658	
659	                const clearError = (field) => {
660	                    const error = field.parentElement.querySelector('.field-error');
661	                    if (error) {
662	                        error.classList.remove('show');
663	                    }
664	                    field.setAttribute('aria-invalid', 'false');
665	                };
666	
667	                const validateField = (field) => {
668	                    const value = field.value.trim();
669	
670	                    if (!value) {
671	                        showError(field, 'This field is required');
672	                        return false;
673	                    }
674	
675	                    if (!field.checkValidity()) {
676	                        const message = field.type === 'email'
677	                            ? 'Please enter a valid email address'
678	                            : 'Invalid input';
679	                        showError(field, message);
680	                        return false;
681	                    }
682	
683	                    clearError(field);
684	                    return true;
685	                };
686	
687	                const inputs = contactForm.querySelectorAll('input, textarea');
688	                inputs.forEach(input => {
689	                    input.addEventListener('blur', () => validateField(input));
690	                });
691	
692	                contactForm.addEventListener('submit', function(e) {
693	                    e.preventDefault();
694	                    let isValid = true;
695	                    const feedback = document.getElementById('form-feedback');
696	                    feedback.className = 'form-feedback';
697	
698	                    inputs.forEach(input => {
699	                        if (!validateField(input)) isValid = false;
700	                    });
701	
702	                    if (!isValid) {
703	                        feedback.className = 'form-feedback error';
704	                        feedback.textContent = 'Please correct the errors above and try again.';
705	                        feedback.focus();
706	                        return;
707	                    }
708	
709	                    const submitBtn = document.getElementById('submit-btn');
710	                    submitBtn.disabled = true;
711	                    const originalHTML = submitBtn.innerHTML;
712	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';
713	
714	                    const formData = new FormData(contactForm);
715	                    fetch('/contact', {
716	                        method: 'POST',
717	                        body: formData
718	                    })
719	                    .then(response => {
720	                        if (response.ok) {
721	                            feedback.className = 'form-feedback success';
722	                            feedback.textContent = 'Thank you for your message! We\'ll be in touch soon.';
723	                            contactForm.reset();
724	                            inputs.forEach(input => clearError(input));
725	                        } else {
726	                            throw new Error('Submission failed');
727	                        }
728	                    })
